param([Parameter(Mandatory=$true)][ValidateSet('CPU','GPU')][string]$Backend,[Parameter(Mandatory=$true)][ValidateSet('Run','Review')][string]$Action,[Parameter(Mandatory=$true)][string]$AdmissionReceipt,[switch]$ExecutionAuthorized)
# One explicit legacy-positive-damping solver OR pure-reader action; never run an old control.
$ErrorActionPreference='Stop';$Backend=$Backend.ToUpperInvariant();$Action=if($Action -ieq 'Run'){'Run'}else{'Review'};$tests=Split-Path -Parent $PSScriptRoot;$logs=Join-Path $tests 'logs';$case=Split-Path -Parent $tests;$tag='upl_damp_off_'+$Backend+'_r1'
$folder=Join-Path $tests ('outputs\'+$tag);$review=Join-Path $tests ('outputs\'+$tag+'_native');$runPath=Join-Path $logs ($tag+'.run.json');$exactPath=Join-Path $logs ($tag+'.exact.json');$callPath=Join-Path $logs ($tag+'_'+$Action.ToLowerInvariant()+'.call.json');$log=Join-Path $logs ($tag+'_'+$Action.ToLowerInvariant()+'.log');$cpu=$Backend -ceq 'CPU';$cfg=if($cpu){'ReleaseCPU'}else{'Release'};$steps=if($cpu){2001}else{15000};$samples=if($cpu){21}else{151}
function E([string]$p){$f=Get-Item -LiteralPath $p;[ordered]@{path=$f.FullName;bytes=[long]$f.Length;sha256=(Get-FileHash -LiteralPath $p -Algorithm SHA256).Hash.ToLowerInvariant()}}
function J([string]$p){[IO.File]::ReadAllText($p)|ConvertFrom-Json}
function Need([bool]$ok,[string]$why){if(!$ok){throw $why}}
function V($rows){foreach($e in $rows){Need ($e.path -and $null -ne $e.bytes -and $e.sha256) 'Missing Entry';$a=E $e.path;Need ($a.bytes -eq $e.bytes -and $a.sha256 -ieq $e.sha256) ('Changed artifact: '+$e.path)}}
function Fresh($paths){foreach($p in $paths){Need (!(Test-Path -LiteralPath $p)) ('Retained artifact protected: '+$p)}}
function Save([string]$p,$v){Fresh @($p);[IO.File]::WriteAllText($p,($v|ConvertTo-Json -Depth 18)+[Environment]::NewLine,(New-Object Text.UTF8Encoding($false)))}
function N([string]$s){$n=[double]::Parse($s,[Globalization.CultureInfo]::InvariantCulture);Need (![double]::IsNaN($n) -and ![double]::IsInfinity($n)) 'Nonfinite diagnostic';return $n}
function HG([string]$text){
  Need ($text.Contains('Finished execution (code=0)') -and $text -match 'SoilDamping="BuiFukagawa2013"' -and $text -match 'SoilDampingCoef=0\.04(?:\s|$)' -and $text -match 'SoilHourglassXi: 0\.1\s' -and $text.Contains('SoilBoundaryDerivativeSPR="MirroredWallDerivatives"') -and $text.Contains('Viscosity="Artificial"') -and $text -match '(?m)^\s*Visco=0\.1\s*$' -and $text -match 'Excluded particles[.]+:\s*0(?:\s|$)') 'Actual positive legacy damping/HG/SPR/viscosity/no-loss gate rejected'
  $s=[regex]::Match($text,'Steps of simulation[.]+:\s*(\d+)');$h=[regex]::Match($text,'SoilHourglass: forcecalls=(\d+) predictorupdates=(\d+) correctorupdates=(\d+) ratecalls=(\d+)');$c=[regex]::Match($text,'SoilHourglass: ratecalculations=(\d+) endpoint_rate_reuses=(\d+)');$d=[regex]::Match($text,'max\(dt/tau\)=([^ ]+) spinbound=([^\r\n]+)')
  Need ($s.Success -and [int]$s.Groups[1].Value -eq $steps -and $h.Success -and $c.Success -and $d.Success) 'Actual original HG counters missing'
  Need ([int]$h.Groups[1].Value -eq 2*$steps -and [int]$h.Groups[2].Value -eq $steps -and [int]$h.Groups[3].Value -eq $steps -and [int]$h.Groups[4].Value -eq 2*$steps -and [int]$c.Groups[1].Value -eq $steps+1 -and [int]$c.Groups[2].Value -eq $steps-1 -and (N $d.Groups[1].Value) -ge 0 -and (N $d.Groups[1].Value) -le 0.2 -and (N $d.Groups[2].Value) -ge 0 -and (N $d.Groups[2].Value) -lt 0.01) 'Original HG count/cache/dt/spin limits rejected'
}
Need $ExecutionAuthorized.IsPresent 'Root full-read plus explicit single-action authorization required';Fresh @($callPath,$log);if($Action -ceq 'Run'){Fresh @($folder,$runPath)}else{Fresh @($review,$exactPath)}
$gate=J $AdmissionReceipt;Need ($gate.stage -ceq 'upl_damp_off_admission_r1' -and $gate.passed -and $gate.allowed_jobs -ccontains $tag -and $gate.physical_acceptance -eq $false) 'Exact OFF job requires root admission'
$buildPath=Join-Path $logs ('upl_damp_'+$cfg+'_r2.build.json');$b=J $buildPath;Need ($b.passed -and $b.stage -ceq 'upl_damp_build_r2' -and $b.configuration -ceq $cfg -and $b.source_bindings_unchanged -and $b.canonical_programs_unchanged -and $b.runtime_unchanged -and $b.exact_object_basename_closure -and $b.objects_include_project_main -and @($b.objects).Count -eq $(if($cpu){86}else{111}) -and @($b.source_snapshot).Count -eq 265 -and @($b.runtime).Count -eq 4 -and @($b.canonical_programs_before).Count -eq 7) 'Passed current corrected authoritative build required'
$bc=J $b.project_call.path;Need ($bc.owned_call_exited -and $bc.typed_LASTEXITCODE_captured_immediately -and $bc.exit_code -is [int] -and $bc.exit_code -eq 0 -and !$bc.invocation_failure -and $bc.program.sha256 -ceq $b.build_tool.sha256 -and ($bc.arguments -join [char]0) -ceq ($b.arguments -join [char]0)) 'Actual current project-build typed exit/vector differs'
$smokePath=Join-Path $logs ('upl_damp_'+$Backend+'_smoke_r1.native.json');$sm=J $smokePath;$smRun=J $sm.source_run.path;$smCall=J $smRun.call.path
Need ($sm.passed -and $sm.stage -ceq 'upl_damp_native_r1' -and $sm.backend -ceq $Backend -and $sm.window -ceq 'smoke' -and $sm.original_native_guards_passed -and $sm.bindings_unchanged -and $smRun.passed -and $smCall.owned_call_exited -and $smCall.typed_LASTEXITCODE_captured_immediately -and $smCall.exit_code -is [int] -and $smCall.exit_code -eq 0 -and !$smCall.invocation_failure) 'Own actual smoke/native safety prerequisite missing'
