$etaPath=Join-Path $logs ('upl_damp_'+$Backend+'_eta0_exact_r1.check.json');$eta=J $etaPath;Need ($eta.passed -and $eta.stage -ceq 'upl_damp_compare_r1' -and $eta.case -ceq ($Backend+'_eta0_exact') -and $eta.gates.all12_saved_export_representations_exact -and $eta.physical_acceptance -eq $false) 'Own actual eta0 exact compatibility gate missing'
$etaNative=J $eta.native_checks[0].path;$etaRun=J $etaNative.source_run.path;Need ($etaNative.passed -and $etaRun.passed -and $etaRun.source_build.sha256 -ceq (E $buildPath).sha256) 'Eta0 must bind this corrected same-backend Release build'
$oldRunPath=Join-Path $logs $(if($cpu){'upl_case02_flux_legacy_off_r1.run.json'}else{'upl_gpu_column_off_r1.run.json'});$old=J $oldRunPath;$oldCallE=if($cpu){$old.owned_exit_record}else{$old.call};$oc=J $oldCallE.path
Need ($old.passed -and $oc.owned_call_exited -and $oc.typed_LASTEXITCODE_captured_immediately -and $oc.exit_code -is [int] -and $oc.exit_code -eq 0 -and !$oc.invocation_failure) 'Retained same-backend actual positive-damping control must have owned exit0'
$oldExactPath=Join-Path $logs $(if($cpu){'upl_case02_flux_legacy_off_r1.exact.json'}else{'upl_gpu_column_off_r1.exact.json'});$oe=J $oldExactPath;Need ($oe.passed -and !$oe.physical_acceptance) 'Retained control exact/safety review missing'
if($cpu){Need ($oe.compared_samples -eq 21 -and $oe.all_original15_typed_prefix_byte_exact -and $oe.all_clock28_prefix_byte_exact -and $oe.native_and_fixed_ID_files_byte_exact) 'Original CPU21 exact control scope differs'}else{Need ($oe.all_original15_typed_exact -and $oe.actual_clock_step_dterror_exact -and $oe.original_HG_guard_preserved -and $oe.source_run.sha256 -ceq (E $oldRunPath).sha256) 'Original GPU151 exact control scope differs'}
$prefix=Join-Path $tests $(if($cpu){'outputs\upl_case02_legacy_off_r1_seed\upl_case02_legacy_off_r1'}else{'outputs\upl_gpu_public_explicit_off_r1_seed\symc_1d_short_r1_gpu_old'});$oldFolder=Join-Path $tests $(if($cpu){'outputs\upl_case02_flux_legacy_off_r1'}else{'outputs\upl_gpu_column_off_r1'});$oldData=Join-Path $oldFolder 'data'
$seedSHA=if($cpu){@('673bb124fcb6f6ddbaf44e0a0b0526127d50666f07c5c584f0093d3ae55f9c86','f2836ffeb049fc777de7687608dd5dfbece81f78440bdc01f21890ee3e3fedac','0509139e4fee0c57d3b480f213c4b9062cf467ce6a24c0a1d13d87148a885f97')}else{@('dd73af99f490461c2a9ed92d6264211c2546f9630b27835aa9577aa8fe02bb6c','f800134f86620e780336d066fa71b712df72144ad861e20fb08f023d322c410e','f556107b01ee310437cf9e0c0d7c0b6d5cbe7e23b8b85183617318a3cf2f9699')}
$seed=@((E ($prefix+'.xml')),(E ($prefix+'.bi4')),(E ($prefix+'_Normals.nbi4')));for($i=0;$i -lt 3;$i++){Need ($seed[$i].sha256 -ceq $seedSHA[$i]) 'Retained backend-specific seed changed'}
$x=New-Object Xml.XmlDocument;$x.Load($seed[0].path);foreach($p in @(@('SoilDamping','1'),@('SoilDampingCoef','0.04'),@('SoilHourglassXi','0.1'),@('SoilBoundaryDerivativeSPR','1'),@('Visco','0.1'))){$n=$x.SelectNodes('/case/execution/parameters/parameter[@key="'+$p[0]+'"]');Need ($n.Count -eq 1 -and (N ($n[0].GetAttribute('value'))) -eq (N $p[1])) 'Original positive damping/HG/SPR/viscosity input differs'}
$expected=@($(if($cpu){'-cpu'}else{'-gpu'}),'-ompthreads:1','-stable','-mdbc',$prefix,$oldFolder,'-dirdataout','data','-svres','-svextraparts:1',('-nsteps:'+$steps));Need (($oc.arguments -join [char]0) -ceq ($expected -join [char]0)) 'Only old output directory may change in actual solver argv';$argv=@($oc.arguments);$argv[5]=$folder
$oldOut=@($old.files|Where-Object {[IO.Path]::GetFileName($_.path) -ceq 'Run.out'});Need ($oldOut.Count -eq 1) 'Retained actual Run.out identity missing';HG ([IO.File]::ReadAllText($oldOut[0].path))
$bindings=@((E $PSCommandPath),(E (Join-Path $tests 'notes\upl_damp_off_r1.json')),(E $AdmissionReceipt),(E $buildPath),(E $smokePath),$sm.source_run,$smRun.call,$sm.reader_call,$sm.completion,(E $etaPath),$eta.native_checks[0],$etaNative.source_run,(E $oldRunPath),$oldCallE,(E $oldExactPath),$oc.program,$oldOut[0],$b.program,$b.project_call,$b.build_tool,$b.log,$b.binlog)+$seed+@($gate.inputs)+@($old.files)+@($b.inputs)+@($b.objects)+@($b.canonical_programs_before)+@($eta.inputs)+@($eta.files)
foreach($p in $b.source_snapshot){$bindings+=@($p.original,$p.snapshot)};foreach($p in @($b.documentation_snapshot,$b.case_readme_snapshot)){$bindings+=@($p.original,$p.snapshot)};foreach($p in $b.runtime){$bindings+=@($p.original,$p.copy)};foreach($p in $b.compiler_linker_command_tlogs){$bindings+=@($p.original,$p.snapshot)};if($b.environment){$bindings+=@($b.environment)}
$tool=$b.program;$oldNative=$null;$readerHelper=$null
if($Action -ceq 'Review'){
  $r=J $runPath;$rc=J $r.call.path;Need ($r.passed -and $r.backend -ceq $Backend -and $r.source_build.sha256 -ceq (E $buildPath).sha256 -and $r.bindings_unchanged -and $rc.owned_call_exited -and $rc.typed_LASTEXITCODE_captured_immediately -and $rc.exit_code -is [int] -and $rc.exit_code -eq 0 -and !$rc.invocation_failure -and $rc.program.sha256 -ceq $b.program.sha256) 'Own completed fresh OFF solve required before pure reader';$bindings+=@((E $runPath),$r.call)+@($r.files)
  $hp=Join-Path $logs $(if($cpu){'upl_case02_reader_ReleaseCPU_r2.helper.json'}else{'upl_gpu_public_off_reader_Release_r2.helper.json'});$h=J $hp;$readerHelper=E $hp;$tool=$h.program;Need ($h.exact_link_closure_verified -and $h.program.sha256 -ceq $(if($cpu){'14dbc519ef623829a48e03c389e0c876c6b96293f56b3e464468ee7c59c7d5c9'}else{'0e3eaa27ea3e422b46a119e40670b19b44dd3fe9dd8fbedd89f52718a0ed338c'})) 'Accepted immutable pure OFF reader identity differs';if($cpu){Need $h.passed 'Accepted CPU structural reader helper failed'}else{Need ($h.fixture -ceq 'OffReader' -and $h.status -ceq 'actual_authoritative_GPU_objects_helper_linked_not_run' -and $h.offline_reader_only) 'Accepted GPU pure-reader helper status differs'}
  $bindings+=@($readerHelper,$tool);foreach($e in @($h.compile_call,$h.link_call)){$hc=J $e.path;Need ($hc.owned_call_exited -and $hc.exit_code -is [int] -and $hc.exit_code -eq 0) 'Historical reader actual compiler/linker exit0 missing';$bindings+=@($e,$hc.program,$hc.log)};foreach($p in $h.runtime){$bindings+=@($p.copy)}
  if($cpu){$oldNative=J (Join-Path $logs 'upl_case02_flux_legacy_off_r1.native.check.json');Need ($oldNative.passed -and $oldNative.owned_reader_exit0 -and $oldNative.exit_code -eq 0 -and $oldNative.sealed_solver.sha256 -ceq (E $oldRunPath).sha256) 'Retained CPU21 typed exports missing';$bindings+=@((E (Join-Path $logs 'upl_case02_flux_legacy_off_r1.native.check.json')),$oldNative.completion,$oldNative.owned_exit_record)+@($oldNative.files);$argv=@('--read-off',(Join-Path $folder 'data'),'21','0.00001',$review)}else{$argv=@('--compare',$oldData,(Join-Path $folder 'data'),$review)}
}
V $bindings;$active=@(Get-CimInstance Win32_Process -Filter "Name LIKE 'DualSPHysics%.exe' OR Name LIKE 'upl_%.exe'");Need ($active.Count -eq 0) 'Another project solver/helper is active; no duplicate launch'
$code=$null;$failure=$null;$started=[DateTime]::UtcNow.ToString('o');$saved=$ErrorActionPreference;[IO.File]::WriteAllBytes($log,[byte[]]@());Push-Location $case
try{$ErrorActionPreference='Continue';$global:LASTEXITCODE=$null;& $tool.path @argv 2>&1|Tee-Object -FilePath $log -Append|Out-Host;$code=$LASTEXITCODE}catch{$failure=$_.Exception.Message}finally{Pop-Location;$ErrorActionPreference=$saved}
Save $callPath ([ordered]@{program=$tool;arguments=$argv;working_directory=$case;started_utc=$started;ended_utc=[DateTime]::UtcNow.ToString('o');direct_native_call=$true;typed_LASTEXITCODE_captured_immediately=($code -is [int]);owned_call_exited=($code -is [int]);exit_code=$code;invocation_failure=$failure;log=(E $log);actual_solver_call=($Action -ceq 'Run');pure_native_reader=($Action -ceq 'Review');physical_acceptance=$false})
# The actual typed exit is sealed before any raw/completion/exact analysis.
$files=@();$completion=$null;$unchanged=$false;$exact=$false;$nativeFrames=0
try{
  Need ($code -is [int] -and $code -eq 0 -and !$failure) 'Owned action failed; preserve partials, no automatic retry';HG ([IO.File]::ReadAllText((Join-Path $folder 'Run.out')))
  $parts=@(Get-ChildItem -LiteralPath (Join-Path $folder 'data') -File -Filter 'Part_*.bi4');$nativeFrames=$parts.Count;$wanted=@(0..($samples-1)|ForEach-Object {'Part_{0:D4}.bi4' -f $_});Need ($nativeFrames -eq $samples -and !(Compare-Object ($parts.Name|Sort-Object) ($wanted|Sort-Object))) 'Exact actual native frame sequence differs'
  if($Action -ceq 'Review'){
    $completion=E (Join-Path $review $(if($cpu){'completion.json'}else{'complete.json'}));$d=J $completion.path
    if($cpu){
      Need ($d.passed -and $d.stage -ceq 'upl_case02_native_r1' -and $d.backend -ceq 'CPU' -and $d.samples -eq 21 -and $d.original_typed_arrays -eq 15 -and $d.total_native_count -eq 1040 -and $d.public_model_metadata_absent_global_and_part -and !$d.native_PosDiv_present -and !$d.native_V_rho_k_present -and $d.native_J_arrays -eq 0 -and $d.no_exclusions -and $d.all_original_fields_finite -and $d.completed_steps_from_last_saved_step -eq 2001 -and $d.noninitial_signed_dterror_intervals -eq 20 -and $d.max_noninitial_signed_dterror_s -le 1e-14 -and !$d.physical_acceptance) 'CPU21 original typed/clock/absence guards rejected'
      foreach($leaf in @('original15.bin','clock.bin','native_ids.csv','fixed_ids.csv','history.csv')){$oldLeaf=@($oldNative.files|Where-Object {[IO.Path]::GetFileName($_.path) -ceq $leaf});$fresh=E (Join-Path $review $leaf);Need ($oldLeaf.Count -eq 1 -and $fresh.bytes -eq $oldLeaf[0].bytes -and $fresh.sha256 -ceq $oldLeaf[0].sha256) ('CPU all-native physical/clock export differs: '+$leaf)};$exact=$true
    }else{
      Need ($d.passed -and $d.frames -eq 151 -and $d.native_count -eq 1040 -and $d.fixed_count -eq 40 -and $d.soil_count -eq 1000 -and $d.original_arrays -eq 15 -and $d.compared_bytes -eq 25126400 -and $d.different_bytes -eq 0 -and $d.all_native_original15_typed_bits_exact -and $d.actual_time_step_signed_dterror_exact -and $d.typed_signed_dterror_present_finite_safe -and $d.dynamic_arrays_and_metadata_absent_both -and $d.native_set_elastic_finite_no_exclusions -and $d.sequential_accumulated_binary64_clock_checked -and $d.actual_steps -eq 15000 -and $d.max_signed_dterror_s -le 1e-14 -and !$d.solver_or_restart_called -and !$d.physical_acceptance) 'GPU151 exact original15/clock/absence guards rejected';$rows=@(Import-Csv -LiteralPath (Join-Path $review 'comparison.csv'));Need ($rows.Count -eq 151) 'GPU151 comparison rows differ';for($i=0;$i -lt 151;$i++){Need ([int]$rows[$i].part -eq $i -and [int]$rows[$i].arrays -eq 15 -and [int]$rows[$i].native_count -eq 1040 -and [int]$rows[$i].compared_bytes -eq 166400 -and [int]$rows[$i].different_bytes -eq 0) 'GPU151 per-frame exact coverage differs'};$exact=$true
    }
  }
}catch{$failure=$_.Exception.Message}
try{V $bindings;$unchanged=$true}catch{if(!$failure){$failure=$_.Exception.Message}};$target=if($Action -ceq 'Run'){$folder}else{$review};if(Test-Path -LiteralPath $target){$files=@(Get-ChildItem -LiteralPath $target -File -Recurse|Sort-Object FullName|ForEach-Object {E $_.FullName})}
$passed=(!$failure -and $unchanged -and $code -is [int] -and $code -eq 0 -and $nativeFrames -eq $samples -and ($Action -ceq 'Run' -or $exact));$record=if($Action -ceq 'Run'){$runPath}else{$exactPath}
Save $record ([ordered]@{stage='upl_damp_off_r1';action=$Action;passed=[bool]$passed;backend=$Backend;configuration=$cfg;source_build=(E $buildPath);program=$b.program;admission=(E $AdmissionReceipt);smoke_native=(E $smokePath);eta0_exact=(E $etaPath);retained_control=(E $oldRunPath);retained_exact=(E $oldExactPath);reader_helper=$readerHelper;source_run=$(if($Action -ceq 'Review'){E $runPath}else{$null});call=(E $callPath);arguments=$argv;input_prefix=$prefix;native_frames=$nativeFrames;steps=$steps;native_count=1040;original_arrays=15;all_original15_typed_exact=[bool]($passed -and $exact);actual_clock_step_dterror_exact=[bool]($passed -and $exact);dynamic_arrays_and_metadata_absent=[bool]($passed -and $exact);original_positive_damping_HG_SPR_guards_preserved=[bool]$passed;bindings_unchanged=$unchanged;inputs=$bindings;files=$files;completion=$completion;paths=@{solver_dir=$folder;native_dir=$review};old_solver_rerun=$false;old_current_source_originals_asserted_current=$false;new_reader_or_build_invoked=$false;physical_acceptance=$false;failure=$failure})
if(!$passed){throw "One OFF action failed; preserve $record and partials, no automatic retry"};Write-Output "One OFF action sealed: $record"
